import { DataTable, PageHeader, SectionHeader, type DataTableColumn } from '@gntik-ai/blocks';
import { Plus } from '@gntik-ai/icons';
import {
  Badge,
  Button,
  Card,
  CardBody,
  CardHeader,
  CardTitle,
  EmptyState,
  HStack,
  OverflowList,
  Page,
  SimpleSelect,
  Stack,
  StatusTag,
  Text,
  Timestamp,
  TreeList,
  type BreadcrumbItem,
  type StatusDefinition,
} from '@gntik-ai/ui';
import { useId, useState } from 'react';
import { ConsoleShell, type ConsoleShellProps } from '../shared/ConsoleShell';
import {
  buildResourceTree,
  groupByLabels,
  groupRows,
  kindIcons,
  resourceTreeBreadcrumbs,
  rowsUnder,
  treeResources,
  type ResourceGroupBy,
  type TreeResource,
} from './data';

export interface ResourceTreeProps {
  resources: TreeResource[];
  defaultGroupBy: ResourceGroupBy;
  /** Initially selected tree node (`team:<name>` or `project:<name>`); none = every resource. */
  defaultNodeId: string | null;
  onOpen: (resource: TreeResource) => void;
  onCreate: () => void;
  breadcrumbs: BreadcrumbItem[];
  currentHref: string;
  shell: Omit<ConsoleShellProps, 'children'>;
}

const STATUSES: Record<string, StatusDefinition> = {
  healthy: { label: 'Healthy', tone: 'success' },
  degraded: { label: 'Degraded', tone: 'warning' },
  stopped: { label: 'Stopped', tone: 'neutral' },
};

const GROUP_ITEMS = (Object.keys(groupByLabels) as ResourceGroupBy[]).map((value) => ({ value, label: groupByLabels[value] }));

function columns(onOpen?: (r: TreeResource) => void): DataTableColumn<TreeResource>[] {
  return [
    {
      id: 'name',
      header: 'Name',
      accessor: (r) => r.name,
      sortable: true,
      cell: (r) => {
        const Icon = kindIcons[r.kind];
        return (
          <span className="inline-flex items-center gap-2">
            <Icon size={14} aria-hidden className="shrink-0 text-muted-foreground" />
            {onOpen ? (
              <button type="button" onClick={() => onOpen(r)} className="font-medium text-foreground underline-offset-2 hover:underline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring">
                {r.name}
              </button>
            ) : (
              <span className="font-medium text-foreground">{r.name}</span>
            )}
          </span>
        );
      },
    },
    { id: 'project', header: 'Project', accessor: (r) => r.project, sortable: true, variant: 'muted' },
    { id: 'region', header: 'Region', accessor: (r) => r.region, variant: 'mono' },
    { id: 'status', header: 'Status', accessor: (r) => r.status, cell: (r) => <StatusTag status={r.status} statuses={STATUSES} /> },
    {
      id: 'tags',
      header: 'Tags',
      cell: (r) => (
        <OverflowList
          label={`${r.name} tags`}
          items={r.tags}
          max={2}
          renderItem={(t) => (
            <Badge variant="outline" size="sm">
              {t}
            </Badge>
          )}
          renderOverflowItem={(t) => t}
        />
      ),
    },
    { id: 'updated', header: 'Updated', accessor: (r) => r.updatedAt, sortable: true, cell: (r) => <Timestamp value={r.updatedAt} className="text-muted-foreground" /> },
  ];
}

/** Resource index browsed by a team → project TreeList, with grouped DataTables and tag overflow. */
export default function ResourceTreePage(props: Partial<ResourceTreeProps>) {
  const {
    resources = treeResources,
    defaultGroupBy = 'kind',
    defaultNodeId = null,
    onOpen,
    onCreate,
    breadcrumbs = resourceTreeBreadcrumbs,
    currentHref = '/resources',
    shell,
  } = props;
  const [nodeId, setNodeId] = useState<string | null>(defaultNodeId);
  const [groupBy, setGroupBy] = useState<ResourceGroupBy>(defaultGroupBy);
  const ids = useId();
  const tree = buildResourceTree(resources);
  const rows = rowsUnder(resources, nodeId);
  const groups = groupRows(rows, groupBy);
  const scope = nodeId ? nodeId.split(':')[1] : 'All resources';
  const cols = columns(onOpen);

  return (
    <ConsoleShell breadcrumbs={breadcrumbs} currentHref={currentHref} {...shell}>
      <Page
        width="wide"
        header={
          <PageHeader
            breadcrumbs={null}
            title="Resources"
            description="Services, databases, buckets and queues by team and project."
            status=""
            meta={[]}
            tabs={null}
            actions={[{ label: 'New resource', icon: Plus, onClick: onCreate }]}
          />
        }
      >
        <div className="grid gap-6 lg:grid-cols-[17rem_minmax(0,1fr)]">
          <Card className="self-start">
            <CardHeader divided>
              <CardTitle as="h2">Teams</CardTitle>
            </CardHeader>
            <CardBody className="p-2">
              <Button variant="ghost" size="sm" className="mb-1 w-full justify-start" aria-pressed={nodeId === null} onClick={() => setNodeId(null)}>
                All resources
              </Button>
              <TreeList
                aria-label="Teams and projects"
                nodes={tree}
                defaultExpanded={tree.map((n) => n.id)}
                selectionMode="single"
                selected={nodeId ? [nodeId] : []}
                onSelectedChange={(next) => setNodeId(next[0] ?? null)}
              />
            </CardBody>
          </Card>
          <Stack gap={6} className="min-w-0">
            <HStack gap={3} wrap justify="between">
              <Text id={`${ids}-scope`} as="span" variant="label" aria-live="polite">
                {scope} · {rows.length === 1 ? '1 resource' : `${rows.length} resources`}
              </Text>
              <HStack gap={2}>
                <Text as="span" variant="supporting" tone="muted">
                  Group by
                </Text>
                <SimpleSelect
                  aria-label="Group by"
                  size="sm"
                  items={GROUP_ITEMS}
                  value={groupBy}
                  onValueChange={(v) => v && setGroupBy(v)}
                  className="w-32"
                />
              </HStack>
            </HStack>
            {groups.length === 0 ? (
              <EmptyState size="sm" titleAs="h2" title="No resources here" description="Pick another team or project." />
            ) : (
              groups.map((g) => (
                <section key={g.key} aria-labelledby={`${ids}-${g.key}`}>
                  <SectionHeader headingId={`${ids}-${g.key}`} title={g.label} count={g.rows.length} as="h2" />
                  <DataTable<TreeResource>
                    rows={g.rows}
                    columns={cols}
                    caption={`${g.label} resources`}
                    getRowLabel={(r) => r.name}
                    paginated={false}
                    showDensityToggle={false}
                    showColumnMenu={false}
                    defaultSort={{ columnId: 'name', direction: 'ascending' }}
                  />
                </section>
              ))
            )}
          </Stack>
        </div>
      </Page>
    </ConsoleShell>
  );
}

import { Building2, Database, FolderKanban, HardDrive, ListOrdered, Server, type LucideIcon } from '@gntik-ai/icons';
import type { BreadcrumbItem, TreeNode } from '@gntik-ai/ui';

export type ResourceKind = 'service' | 'database' | 'bucket' | 'queue';
export type ResourceGroupBy = 'kind' | 'region' | 'team';

export interface TreeResource {
  id: string;
  name: string;
  kind: ResourceKind;
  team: string;
  project: string;
  region: string;
  status: 'healthy' | 'degraded' | 'stopped';
  tags: string[];
  /** ISO date of the last change. */
  updatedAt: string;
}

export const kindLabels: Record<ResourceKind, string> = { service: 'Services', database: 'Databases', bucket: 'Buckets', queue: 'Queues' };
export const kindIcons: Record<ResourceKind, LucideIcon> = { service: Server, database: Database, bucket: HardDrive, queue: ListOrdered };
export const groupByLabels: Record<ResourceGroupBy, string> = { kind: 'Kind', region: 'Region', team: 'Team' };

export const resourceTreeBreadcrumbs: BreadcrumbItem[] = [{ label: 'Acme Industries', href: '/overview' }, { label: 'Resources' }];

export const treeResources: TreeResource[] = [
  { id: 'r1', name: 'orders-api', kind: 'service', team: 'Commerce', project: 'checkout', region: 'eu-west-1', status: 'healthy', tags: ['production', 'pci', 'tier-1'], updatedAt: '2026-09-30' },
  { id: 'r2', name: 'orders-db', kind: 'database', team: 'Commerce', project: 'checkout', region: 'eu-west-1', status: 'healthy', tags: ['production', 'pci', 'backups', 'encrypted'], updatedAt: '2026-09-28' },
  { id: 'r3', name: 'payment-events', kind: 'queue', team: 'Commerce', project: 'checkout', region: 'eu-west-1', status: 'degraded', tags: ['production', 'on-call'], updatedAt: '2026-10-02' },
  { id: 'r4', name: 'catalog-web', kind: 'service', team: 'Commerce', project: 'catalog', region: 'us-east-1', status: 'healthy', tags: ['production'], updatedAt: '2026-09-21' },
  { id: 'r5', name: 'catalog-images', kind: 'bucket', team: 'Commerce', project: 'catalog', region: 'us-east-1', status: 'healthy', tags: ['public', 'cdn', 'production'], updatedAt: '2026-09-12' },
  { id: 'r6', name: 'usage-collector', kind: 'service', team: 'Platform', project: 'metering', region: 'eu-west-1', status: 'healthy', tags: ['internal', 'tier-1'], updatedAt: '2026-09-29' },
  { id: 'r7', name: 'usage-warehouse', kind: 'database', team: 'Platform', project: 'metering', region: 'eu-west-1', status: 'stopped', tags: ['analytics', 'staging'], updatedAt: '2026-08-30' },
  { id: 'r8', name: 'audit-archive', kind: 'bucket', team: 'Platform', project: 'compliance', region: 'ap-south-1', status: 'healthy', tags: ['retention-7y', 'encrypted', 'worm', 'legal-hold'], updatedAt: '2026-09-02' },
  { id: 'r9', name: 'export-jobs', kind: 'queue', team: 'Platform', project: 'compliance', region: 'ap-south-1', status: 'healthy', tags: ['internal'], updatedAt: '2026-09-25' },
];

/** Team → project tree with resource counts. Node ids: `team:<name>` and `project:<name>`. */
export function buildResourceTree(rows: readonly TreeResource[]): TreeNode[] {
  const teams = [...new Set(rows.map((r) => r.team))];
  return teams.map((team) => {
    const inTeam = rows.filter((r) => r.team === team);
    const projects = [...new Set(inTeam.map((r) => r.project))];
    return {
      id: `team:${team}`,
      label: team,
      icon: Building2,
      meta: String(inTeam.length),
      children: projects.map((p) => ({ id: `project:${p}`, label: p, icon: FolderKanban, meta: String(inTeam.filter((r) => r.project === p).length) })),
    };
  });
}

/** Rows under a tree node id (`team:…`, `project:…`); `null` = all. */
export function rowsUnder(rows: readonly TreeResource[], nodeId: string | null): TreeResource[] {
  if (!nodeId) return [...rows];
  const [type, name] = nodeId.split(':');
  return rows.filter((r) => (type === 'team' ? r.team === name : r.project === name));
}

/** Groups rows by a field, in first-seen order. */
export function groupRows(rows: readonly TreeResource[], by: ResourceGroupBy): Array<{ key: string; label: string; rows: TreeResource[] }> {
  const keys = [...new Set(rows.map((r) => r[by]))];
  return keys.map((key) => ({ key, label: by === 'kind' ? kindLabels[key as ResourceKind] : key, rows: rows.filter((r) => r[by] === key) }));
}

import {
  AppSidebarFooter,
  AppSidebarHeader,
  AppSidebarNav,
  AppTopbar,
  type AppSidebarFooterProps,
  type AppSidebarHeaderProps,
  type AppTopbarProps,
} from '@gntik-ai/blocks';
import { SidebarLayout, type BreadcrumbItem, type NavGroup, type SidebarLayoutProps, type UserMenuUser, type Workspace } from '@gntik-ai/ui';
import type { ReactNode } from 'react';

export interface ConsoleShellProps
  extends Pick<AppSidebarHeaderProps, 'currentWorkspaceId' | 'onWorkspaceChange' | 'onCreateWorkspace'>,
    Pick<AppSidebarFooterProps, 'usage' | 'helpHref' | 'helpLabel' | 'userMenuItems' | 'onSignOut'>,
    Pick<SidebarLayoutProps, 'sidebarLabel' | 'collapseMode'> {
  /** Page content (usually a <Page>). */
  children: ReactNode;
  /** Sidebar navigation; defaults to the AppSidebar sample groups. */
  nav?: NavGroup[];
  /** Href of the current page, marks the active nav item. */
  currentHref?: string;
  breadcrumbs?: BreadcrumbItem[] | null;
  workspaces?: Workspace[] | null;
  user?: UserMenuUser | null;
  /** Extra AppTopbar props (environment, notifications, theme control…). */
  topbar?: Omit<AppTopbarProps, 'breadcrumbs' | 'user'>;
  /** localStorage key for the collapsed sidebar; `undefined` disables persistence. */
  storageKey?: string;
}

/**
 * The console frame shared by the templates: SidebarLayout with the AppSidebar header, nav and
 * footer, and the AppTopbar (breadcrumb, ⌘K search, notifications, theme, user menu).
 * Templates fill it with a Page; products swap the nav, workspaces, user, usage meter, help
 * link and user-menu items.
 */
export function ConsoleShell({
  children,
  nav,
  currentHref,
  breadcrumbs,
  workspaces,
  currentWorkspaceId,
  onWorkspaceChange,
  onCreateWorkspace,
  user,
  usage,
  helpHref,
  helpLabel,
  userMenuItems,
  onSignOut,
  topbar,
  storageKey,
  sidebarLabel,
  collapseMode,
}: ConsoleShellProps) {
  return (
    <SidebarLayout
      fullScreen
      storageKey={storageKey}
      sidebarLabel={sidebarLabel}
      collapseMode={collapseMode}
      sidebarHeader={({ collapsed }) => (
        <AppSidebarHeader
          collapsed={collapsed}
          workspaces={workspaces}
          currentWorkspaceId={currentWorkspaceId}
          onWorkspaceChange={onWorkspaceChange}
          onCreateWorkspace={onCreateWorkspace}
        />
      )}
      sidebar={({ collapsed }) => <AppSidebarNav groups={nav} currentHref={currentHref} collapsed={collapsed} />}
      sidebarFooter={({ collapsed }) => (
        <AppSidebarFooter
          collapsed={collapsed}
          user={user}
          usage={usage}
          helpHref={helpHref}
          helpLabel={helpLabel}
          userMenuItems={userMenuItems}
          onSignOut={onSignOut}
        />
      )}
      topbar={<AppTopbar breadcrumbs={breadcrumbs} user={user} {...topbar} />}
    >
      {children}
    </SidebarLayout>
  );
}
